window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7138ab8068a900a2"]={"versions": [{"id": "FIG-7138ab8068a900a2", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (Classic Platform) zur Darstellung des Methodikschritts „Generate Base ECU Configuration“. Es zeigt die an dieser Aktivität beteiligten Rollen, Eingangs- und Ausgangs-Arbeitsergebnisse (Work Products / Artefakte) sowie deren Zuordnungs- und Kontrollbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task</strong>:\n<ul class=\"fig-list\"><li><code>Generate Base Ecu Configuration</code> (mittiges Prozess-Symbol).\n</li></ul>\n</li><li><strong>Rolle / Akteur</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Rollen-Symbol oberhalb der Aktivität).\n</li></ul>\n</li><li><strong>Eingangsartefakte</strong>:\n<ul class=\"fig-list\"><li><code>ECU Extract</code> (Briefumschlag-Symbol mit blau gestrichelter Markierung links oben): Multiplizität <code>1</code>, Stereotyp <code>«input»</code>.\n</li><li><code>BSW Module Description</code> (abgeschnitten als <code>BSW Module...</code>, Briefumschlag-Symbol links unten): Multiplizität <code>1..*</code>, Stereotyp <code>«input»</code>.\n</li></ul>\n</li><li><strong>Ausgangsartefakt</strong>:\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Dokument-Symbol rechts): Multiplizität <code>1</code>, Stereotyp <code>«output»</code>.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li>Gerichtete Kontroll-/Datenflusspfeile definieren Input- und Output-Rollen der Artefakte.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> stößt die Aktivität <code>Generate Base Ecu Configuration</code> an bzw. führt diese durch.\n</li><li>Zur Erstellung der initialen Basis-Konfiguration werden genau ein <code>ECU Extract</code> sowie mindestens eine <code>BSW Module Description</code> (<code>1..*</code>) eingelesen und verarbeitet.\n</li><li>Als Ergebnis der Aktivität wird genau eine Sammlung an Konfigurationswerten (<code>ECU Configuration Values</code>, Kardinalität <code>1</code>) erzeugt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt bildet die Nahtstelle zwischen dem System-Design (System Extract / ECU Extract) und der eigentlichen Steuergeräte-Konfiguration (BSW / RTE). Ohne den <code>ECU Extract</code> und die entsprechenden BSW-Modulbeschreibungen kann keine konsistente Grundkonfiguration der BSW angelegt werden. Die Kardinalität <code>1..*</code> erzwingt das Vorhandensein von mindestens einer BSW-Modulbeschreibung. Das generierte Artefakt <code>ECU Configuration Values</code> dient als primäre Basis für alle nachgelagerten Konfigurationsschritte des Steuergeräts.</p>"}, {"id": "FIG-25779e91d55cbcfb", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (Classic Platform) zur Darstellung des Methodikschritts „Generate Base ECU Configuration“. Es zeigt die an dieser Aktivität beteiligten Rollen, Eingangs- und Ausgangs-Arbeitsergebnisse (Work Products / Artefakte) sowie deren Zuordnungs- und Kontrollbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task</strong>:\n<ul class=\"fig-list\"><li><code>Generate Base Ecu Configuration</code> (mittiges Prozess-Symbol).\n</li></ul>\n</li><li><strong>Rolle / Akteur</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Rollen-Symbol oberhalb der Aktivität).\n</li></ul>\n</li><li><strong>Eingangsartefakte</strong>:\n<ul class=\"fig-list\"><li><code>ECU Extract</code> (Briefumschlag-Symbol mit blau gestrichelter Markierung links oben): Multiplizität <code>1</code>, Stereotyp <code>«input»</code>.\n</li><li><code>BSW Module Description</code> (abgeschnitten als <code>BSW Module...</code>, Briefumschlag-Symbol links unten): Multiplizität <code>1..*</code>, Stereotyp <code>«input»</code>.\n</li></ul>\n</li><li><strong>Ausgangsartefakt</strong>:\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Dokument-Symbol rechts): Multiplizität <code>1</code>, Stereotyp <code>«output»</code>.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li>Gerichtete Kontroll-/Datenflusspfeile definieren Input- und Output-Rollen der Artefakte.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> stößt die Aktivität <code>Generate Base Ecu Configuration</code> an bzw. führt diese durch.\n</li><li>Zur Erstellung der initialen Basis-Konfiguration werden genau ein <code>ECU Extract</code> sowie mindestens eine <code>BSW Module Description</code> (<code>1..*</code>) eingelesen und verarbeitet.\n</li><li>Als Ergebnis der Aktivität wird genau eine Sammlung an Konfigurationswerten (<code>ECU Configuration Values</code>, Kardinalität <code>1</code>) erzeugt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt bildet die Nahtstelle zwischen dem System-Design (System Extract / ECU Extract) und der eigentlichen Steuergeräte-Konfiguration (BSW / RTE). Ohne den <code>ECU Extract</code> und die entsprechenden BSW-Modulbeschreibungen kann keine konsistente Grundkonfiguration der BSW angelegt werden. Die Kardinalität <code>1..*</code> erzwingt das Vorhandensein von mindestens einer BSW-Modulbeschreibung. Das generierte Artefakt <code>ECU Configuration Values</code> dient als primäre Basis für alle nachgelagerten Konfigurationsschritte des Steuergeräts.</p>"}, {"id": "FIG-191af5107befa9a5", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (Classic Platform) zur Darstellung des Methodikschritts „Generate Base ECU Configuration“. Es zeigt die an dieser Aktivität beteiligten Rollen, Eingangs- und Ausgangs-Arbeitsergebnisse (Work Products / Artefakte) sowie deren Zuordnungs- und Kontrollbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task</strong>:\n<ul class=\"fig-list\"><li><code>Generate Base Ecu Configuration</code> (mittiges Prozess-Symbol).\n</li></ul>\n</li><li><strong>Rolle / Akteur</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Rollen-Symbol oberhalb der Aktivität).\n</li></ul>\n</li><li><strong>Eingangsartefakte</strong>:\n<ul class=\"fig-list\"><li><code>Diagnostic ECU Extract</code> (Briefumschlag-Symbol links oben): Multiplizität <code>0..1</code>, Stereotyp <code>«input»</code>.\n</li><li><code>ECU Extract</code> (Briefumschlag-Symbol links Mitte): Multiplizität <code>1</code>, Stereotyp <code>«input»</code>.\n</li><li><code>BSW Module Description</code> (abgeschnitten als <code>BSW Module...</code>, Briefumschlag-Symbol links unten): Multiplizität <code>1..*</code>, Stereotyp <code>«input»</code>.\n</li></ul>\n</li><li><strong>Ausgangsartefakt</strong>:\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Dokument-Symbol rechts): Multiplizität <code>1</code>, Stereotyp <code>«output»</code>.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li>Gerichtete Kontroll-/Datenflusspfeile definieren Input- und Output-Rollen der Artefakte.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> führt die Aktivität <code>Generate Base Ecu Configuration</code> durch.\n</li><li>Für die Erzeugung der Basis-Konfiguration werden obligatorisch genau ein <code>ECU Extract</code> (<code>1</code>) und mindestens eine <code>BSW Module Description</code> (<code>1..*</code>) sowie optional ein <code>Diagnostic ECU Extract</code> (<code>0..1</code>) als Eingangsdaten herangezogen.\n</li><li>Als Resultat wird genau ein Satz an Konfigurationswerten (<code>ECU Configuration Values</code>, Kardinalität <code>1</code>) generiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die optionale Einbindung des <code>Diagnostic ECU Extract</code> (Kardinalität <code>0..1</code>) erlaubt die frühzeitige Berücksichtigung von Diagnose-Konfigurationsanforderungen bereits bei der Generierung der Basis-ECU-Konfiguration. Weiterhin bleiben das Vorhandensein genau eines <code>ECU Extract</code> und mindestens einer BSW-Modulbeschreibung zwingende Voraussetzungen zur Generierung der initialen <code>ECU Configuration Values</code>.</p>"}], "trans": [{"from": "FIG-7138ab8068a900a2", "to": "FIG-25779e91d55cbcfb", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-25779e91d55cbcfb", "to": "FIG-191af5107befa9a5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neues Eingangs-Artefakt <code>Diagnostic ECU Extract</code> mit Stereotyp <code>«input»</code> und Multiplizität <code>0..1</code> zur Aktivität <code>Generate Base Ecu Configuration</code> hinzugefügt.\n</li><li>Layoutanpassung der Eingangsartefakte auf der linken Seite zur Aufnahme des neuen Extrakts.\n</li></ul>"}]};
